import type { Argv, ArgumentsCamelCase, CommandModule } from 'yargs'
import { validateWorkingDir } from '../../util'
import { cwd } from 'process'
import { logger } from '../../logger'
import * as fs from 'fs'
import open from 'open'
import { createTelemetryClient } from '../../telemetry'
import { Project, Orchestrator } from '@servicenow/sdk-api'
import { type Telemetry, NowConfig } from '@servicenow/sdk-build-core'
import { credentialProvider } from '../../auth'

interface Arguments {
    source: string
    reinstall: boolean
    'open-browser': boolean
    auth: string | undefined
    info: boolean
    store: boolean
    maven: boolean
    async: boolean
    targetUpdateSet: string | undefined
    demoData: boolean
}

export const install: CommandModule<unknown, Arguments> = {
    command: 'install',
    aliases: 'deploy',
    describe: 'Install or update application on instance',
    builder: async (yargs: Argv) => {
        return yargs
            .option('source', {
                describe: `Path to the directory that contains package.json configuration`,
                default: cwd(),
                type: 'string',
            })
            .option('reinstall', {
                describe:
                    'Uninstall and reinstall the application on the instance to ensure metadata on instance matches installation package.\n' +
                    'Warning: Metadata created on-instance that is not present locally will be lost',
                type: 'boolean',
                alias: 'r',
                default: false,
            })
            .option('auth', {
                describe: 'Credential alias to use for authentication with instance',
                type: 'string',
                alias: 'a',
            })
            .option('open-browser', {
                describe: 'Open sys_app page in the default browser on successful install',
                default: false,
                type: 'boolean',
                alias: 'b',
            })
            .option('info', {
                describe: 'Get information from instance for most recent install of this app',
                default: false,
                type: 'boolean',
                alias: 'i',
            })
            .option('store', {
                describe: 'Install the app as a sys_store_app record instead of a sys_app custom application',
                default: false,
                type: 'boolean',
                alias: 's',
                hidden: true,
            })
            .option('async', {
                describe: 'Install the app asynchronously',
                default: false,
                type: 'boolean',
                hidden: true,
            })
            .option('maven', {
                describe: 'Install *-app.zip output from maven assembly',
                default: false,
                type: 'boolean',
                hidden: true,
            })
            .option('targetUpdateSet', {
                describe: 'Upload the output to the target update set',
                type: 'string',
                hidden: true,
            })
            .option('demoData', {
                describe: 'Install demo data',
                type: 'boolean',
                default: true,
            })
    },
    handler: async (args: ArgumentsCamelCase<Arguments>): Promise<void> => {
        let telemetryClient: Telemetry | undefined
        try {
            const credential = await credentialProvider(args.auth)
            telemetryClient = createTelemetryClient(fs, __dirname, credential.getUrl())

            if (args.info) {
                logger.info(
                    `View install information in the Upgrade History table at ${getSummaryURL(credential.getUrl())}`
                )
                return
            }

            logger.info('Starting installation...')
            const workingDir = validateWorkingDir(args.source)
            const config = NowConfig.parseFromDirectory(workingDir, fs, logger)
            const project = new Project({ config, fileSystem: fs, rootDir: workingDir, logger, telemetryClient })
            const orchestrator = new Orchestrator(project, credential)

            const { scopeId, type } = project.getConfig()
            if (type === 'configuration') {
                const updateSetResult = await orchestrator.installConfigurations(
                    args.targetUpdateSet ? { targetUpdateSetId: args.targetUpdateSet } : undefined
                )
                logger.info(`Changes installed successfully to update set: ${updateSetResult}`)
            } else {
                await orchestrator.install({
                    clean: args.reinstall,
                    installAsStoreApp: args.store,
                    installAsync: args.async,
                    demoData: args.demoData,
                })

                const sysAppUrl = getSysAppURL(credential.getUrl(), scopeId, args.store)
                logger.info(`Installation completed. Access the application at: ${sysAppUrl}`)
                if (args.openBrowser) {
                    await open(sysAppUrl)
                }
            }
        } catch (error) {
            logger.error(error)
            process.exitCode = 1
        }
    },
}

function getSysAppURL(host: URL, sysId: string, isStoreApp: boolean) {
    const table = isStoreApp ? 'sys_store_app' : 'sys_app'
    return `${host.origin}/${table}.do?sys_id=${sysId}`
}

export function getSummaryURL(host: URL, sysId?: string) {
    if (sysId) {
        return `${host.origin}/nav_to.do?uri=sys_upgrade_history.do?sys_id=${sysId}`
    }
    return `${host.origin}/sys_upgrade_history_list.do`
}
